def compute(vars):
    current_cost = vars["v1"]
    prior_cost = vars["v2"]

    if prior_cost == 0:
        return None

    increase = current_cost - prior_cost
    change_ratio = increase / prior_cost
    percentage_increase = change_ratio * 100

    return {
        "value": percentage_increase,
        "trace": {
            "current_cost": current_cost,
            "prior_cost": prior_cost,
            "increase": increase,
            "change_ratio": change_ratio,
            "percentage_increase": percentage_increase,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
